head.script:
scwin.trigger1_onclick = function(e) {
    var obj = {
        "id": "test123",
        "title": "test123",
        "start": "20160120",
        "end": "20160121"
    };
    schdule1.addSchedule(obj);
};
scwin.trigger2_onclick = function(e) {
    schdule1.removeschedule("test123");
};
scwin.trigger3_onclick = function(e) {
    /*headerLeftBtn 왼쪽 위 (오늘)
    headerRightBtn:false 오른쪽 위(주일월)
    headerTitle:true 년월 */
    var opt = {
        headerLeftBtn: true,
        headerRightBtn: false,
        headerTitle: true
    };
    schdule1.setHeaderBtn(opt);
};
scwin.trigger4_onclick = function(e) {
    var opt = {
        "sun": {
            "header": {
                "color": "#ff0000"
            },
            "body": {
                "background-color": "#ff0000",
                "opacity": "0.2"
            },
            "num": {
                "color": "#ff0000"
            }
        },
        "sat": {
            "header": {
                "color": "#ff0000"
            },
            "body": {
                "background-color": "#ff0000",
                "opacity": "0.2"
            },
            "num": {
                "color": "#ff0000"
            }
        }
    };
    schdule1.setDayNameStyle(opt);
};
scwin.move = function() {
    debugger
    /*
    var date1 = new Date(2016, 01);
    var date2 = new Date();
    var month = (date2 - date1)/86400000;		
    for(i = 0; i< Math.floor(month/30); i++){
    	WebSquare.wUnit.getJq(".fc-button-group")[0].children[0].click();
    }
    */
    schdule1.gotoCalendar("20160105", {
        noSelectable: true
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.move()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-event-title')[0].innerText", "생일");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-event-title')[1].innerText", "기념일");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-event-title')[2].innerText", "ㅁㅁ");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-event-title')[3].innerText", "기념일");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-event-title')[4].innerText", "ㅠㅠ");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-event-title')[5].innerText", "ㅂㅂ");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
